import{_ as t,o,c as i,a6 as a}from"./chunks/framework.CnPv4DE1.js";const d=JSON.parse('{"title":"Why Self-Help Is Ruining Your Life","description":"","frontmatter":{"title":"Why Self-Help Is Ruining Your Life","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/why-self-help-is-ruining-your-life.md","filePath":"en/letters/why-self-help-is-ruining-your-life.md"}'),n={name:"en/letters/why-self-help-is-ruining-your-life.md"};function s(r,e,l,p,h,u){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="why-self-help-is-ruining-your-life" tabindex="-1">Why Self-Help Is Ruining Your Life <a class="header-anchor" href="#why-self-help-is-ruining-your-life" aria-label="Permalink to &quot;Why Self-Help Is Ruining Your Life&quot;">​</a></h1><p>Dan Koe · 2021-05-12 · <a href="https://thedankoe.com/letters/why-self-help-is-ruining-your-life/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/why-self-help-is-ruining-your-life">返回中文译文</a></p><p>Self-help is making you miserable. Let’s change that.</p><p>This is a topic that has been on my mind recently. I want to clear the room up front by saying that self-help is not inherently bad. It can be good in many cases.</p><p>The energy and information you gain from reading self-help needs to be channeled correctly.</p><p><a href="https://www.youtube.com/embed/Ms6cMzHVEvA?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><h2 id="the-problem-with-self-help" tabindex="-1">The Problem With Self-Help <a class="header-anchor" href="#the-problem-with-self-help" aria-label="Permalink to &quot;The Problem With Self-Help&quot;">​</a></h2><p>Have you ever bought a book and expect your life to change? Don’t lie.</p><p>The titles, sub-titles, and social praise from a book hook our attention. We build false expectations in our heads, order the book with excitement, and start to consume it.</p><p>Here’s the thing… You and I both know that reading alone isn’t going to change your life.</p><p>We end up getting trapped in a cycle of reading with good intentions, but end up reading just to feel good about ourselves.</p><p>This is called mental masturbation.</p><p>Reading about improving yourself but not actually improving yourself.</p><p>Reading to feel good about yourself, to feel like you are actually improving that is.</p><p>In reality, your brain loves collecting those dopamine hits and enforcing the mental masturbation loop further.</p><h2 id="the-difference-between-self-help-and-self-improvement" tabindex="-1">The Difference Between Self-Help and Self-Improvement <a class="header-anchor" href="#the-difference-between-self-help-and-self-improvement" aria-label="Permalink to &quot;The Difference Between Self-Help and Self-Improvement&quot;">​</a></h2><p>Self-help is extrinsic motivation – relying on external factors to motivate you.</p><p>For the David Goggin’s of the world (“fuck motivation, all you need is discipline”), you can start to see the problem here.</p><p>“All you need is discipline,” is partially true.</p><p>The extrinsic motivation we get from self-help books is useful for 3 reasons:</p><ul><li>We are motivated (which can be used as initial momentum into discipline)</li><li>We are equipped with a concept that can change our lives</li><li>We understand how to implement that concept</li></ul><p>The magic happens in the last point. It forms the basis for self-improvement.</p><p>That’s the difference between the two.</p><p>Self-help = unsustainable motivation</p><p>Self-improvement = implementing self-help concepts, seeing results, and cultivating intrinsic motivation</p><h2 id="the-thing-that-can-f-ck-you-up" tabindex="-1">The Thing That Can F*ck You Up <a class="header-anchor" href="#the-thing-that-can-f-ck-you-up" aria-label="Permalink to &quot;The Thing That Can F\\*ck You Up&quot;">​</a></h2><p>Not all self-improvement is created equal.</p><p>Many people fail to understand is that <em>some</em> concepts may not work for you. We are human. We are each different in our own unique ways.</p><p>This is what creates an anti-self-improvement mindset.</p><p>The ones who adopt this mindset implemented a self-help concept, it didn’t work for them, and they go on to tell everyone that it doesn’t work.</p><p>At the same time there are people that swear by the exact same concepts.</p><p>Let’s take the gym for example.</p><p>Some people love bench press, some people hate it.</p><p>Some people say it is a bad exercise for chest growth, others say it’s the best.</p><p>Mechanics, genetics, noobie gains, and muscle insertions aside…</p><p>How can you know that bench press is a good exercise for you without doing it consistently?</p><p>If you implemented this exercise, continuously increased weight, and stuck to it for 6-12 months – THEN you can decide if it’s good or bad.</p><p>This goes for any other concept that can improve your life.</p><p>Trying it for a day, deciding it sucks, and dropping it will f*ck you up.</p><h2 id="a-foundation-of-awareness-house-of-direct-experience" tabindex="-1">A Foundation of Awareness &amp; House of Direct Experience <a class="header-anchor" href="#a-foundation-of-awareness-house-of-direct-experience" aria-label="Permalink to &quot;A Foundation of Awareness &amp; House of Direct Experience&quot;">​</a></h2><p>All true self improvement stems from awareness and is solidified through direct experience.</p><p>Self-help information makes you <em>aware</em> of a problem you may have. It gives you steps to fix it.</p><p>Following those steps (direct experience) for a given amount of time is what improves your life.</p><p>If you have given ample time and still not seen results, awareness comes back into play and the cycle continuous. Continuous improvement.</p><p>If you have a clouded/anxious mind and a self-help book tells you to meditate, you need to meditate on a consistent basis to see if it actually helps you. If it doesn’t, that’s fine.</p><p>Self-help concepts act as a “boost” to your awareness.</p><p>Direct experience helps you understand if it is useful to you.</p><p>If it is useful to you, the intrinsic motivation starts to build.</p><p>If it isn’t useful to you, go back to the awareness step. This is what most people skip.</p><p>The worst thing you could do at this point is write off self-help as a whole.</p><p>That’s how you end up living an average life.</p><p>Show me anyone you aspire to be like that doesn’t have a foundation of continuous improvement in their life. You won’t be able to. If you can, these people aren’t worth aspiring to be like.</p><p>Your business will suffer if you don’t improve yourself as your business grows.</p><p>Your relationships will suffer if you don’t improve yourself as they grow.</p><p>Your health will suffer if you aren’t aware of the hidden problems it is causing.</p><h2 id="tldr" tabindex="-1">TLDR <a class="header-anchor" href="#tldr" aria-label="Permalink to &quot;TLDR&quot;">​</a></h2><p>Self-help is bad if you are reading it to feel like you are actually doing something.</p><p>Self-improvement is good if you develop awareness and intrinsic drivers with time.</p>',58)])])}const c=t(n,[["render",s]]);export{d as __pageData,c as default};
